#!/usr/bin/env node
// 自動修正の結果を TrainLCD/Issues へ返すコメントの本文を組み立てる。
// .github/workflows/auto_fix_from_feedback.yml から呼ばれる前提で、追加の依存を
// 持たず Node 24 の標準機能（ESM）だけで動くようにしている。
//
// エージェントには Issues リポジトリのトークンを渡していない。そのため判断は、
// ワークフローの一時ディレクトリに置かれた verdict.json を通して受け取る。
// 返す内容は次の 3 通りで、どの場合でも必ず何かを返す。
//  - linked:   PR が出来た。そのリンクを返す。
//  - declined: 直せないと判断した。その理由を返す。
//  - failed:   実行が最後まで進まなかった。どこで止まったのかを返す。
//
// failed を黙って握りつぶさないこと。issue を見た人には「調べたうえで何もしな
// かった」のか「そもそも動かなかった」のかが分からず、手つかずの issue を
// 対応済みだと思って読み飛ばすことになる。

import { realpathSync } from 'node:fs';
import { appendFile, readFile, writeFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

// 同じ issue を二度調べさせないための目印。ワークフローは動き出す前にこの
// 綴りを探し、見つかれば何もせずに終わる。
export const MARKER = '<!-- auto-fix-from-feedback -->';
// 失敗の報告には別の目印を使う。MARKER で始まらないので上の確認には引っかからず、
// 次にラベルが付いたときや手動実行でもう一度試せる。一時的な失敗のせいで二度と
// 試せなくなるのを避けたいので、ここは意識して分けている。
export const ERROR_MARKER = '<!-- auto-fix-from-feedback:error -->';

const FOOTER = '_Generated by [Claude Code](https://claude.ai/code)_';

// 理由を書くのはエージェントだが、その材料になるのは利用者の本文なので、信用
// できない入力の影響を受ける。目印を装われると上の確認が働かなくなるので、
// HTML コメントはまとめて取り除く。
const HTML_COMMENT_PATTERN = /<!--[\s\S]*?-->/g;
const MAX_REASON_CHARS = 1200;
// 壊れた verdict.json をそのまま貼らない。見当が付く長さだけ残す。
const MAX_EXCERPT_CHARS = 200;
// 引き継ぎ先は選択肢が決まっているので、想定外の値はそのまま出さない。
const HANDOFF_REPOSITORIES = {
  StationAPI: 'https://github.com/TrainLCD/StationAPI',
  Functions: 'https://github.com/TrainLCD/Functions',
};

// 止まった箇所ごとの文面。あらかじめ決めた言い回しから選んでいるのは、ここを
// エージェントに書かせると、「動かなかった」という事実そのものが本人の申告に
// なってしまうため。
const FAILURE_STAGES = {
  'not-reached': {
    summary: '準備の途中で止まり、エージェントが動き出すところまで進みませんでした。',
    hint: 'checkout・依存のインストール・issue の取得のどれかで失敗しています。',
  },
  'agent-failed': {
    summary: 'エージェントの実行が途中で止まりました。',
    hint: '何を調べたのかも書き残されていないので、原因は分かっていません。',
  },
  'no-verdict': {
    summary: 'エージェントは終了しましたが、調べた結果を書き残していません。',
    hint: 'PR も出来ていません。何をしていたのかは実行ログから追えます。',
  },
  'invalid-verdict': {
    summary: 'エージェントが書き残したファイルを読めませんでした。',
    hint: '調べてはいたようですが、書かれている内容を取り出せていません。',
  },
  'pr-missing': {
    summary: 'エージェントは修正したと書いていますが、PR が見つかりません。',
    hint: 'push か PR の作成に失敗したのかもしれません。',
  },
};

export const sanitizeReason = (reason) =>
  String(reason ?? '')
    .replace(HTML_COMMENT_PATTERN, '')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, MAX_REASON_CHARS);

// 読めた、読めない、そもそも無い、の 3 つを呼び出し側で区別できるようにする。
// どれも判断が無いことに変わりはないが、issue に書くべき内容が違う。
export const parseVerdict = (raw) => {
  if (typeof raw !== 'string' || raw.trim() === '') {
    return { status: 'missing' };
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { status: 'invalid', excerpt: sanitizeReason(raw).slice(0, MAX_EXCERPT_CHARS) };
  }
  if (parsed?.outcome !== 'fixed' && parsed?.outcome !== 'declined') {
    return { status: 'invalid', excerpt: sanitizeReason(raw).slice(0, MAX_EXCERPT_CHARS) };
  }
  return {
    status: 'ok',
    verdict: {
      outcome: parsed.outcome,
      reason: sanitizeReason(parsed.reason),
      handoff: Object.hasOwn(HANDOFF_REPOSITORIES, parsed.handoff) ? parsed.handoff : '',
    },
  };
};

const withFooter = (lines) => [...lines, '', '---', FOOTER, ''].join('\n');

export const renderLinkComment = (prUrl) =>
  withFooter([
    MARKER,
    'フィードバックを起点に自動生成された修正 PR です。',
    '',
    prUrl,
    '',
    '実機で症状を再現して確かめてはいません。レビューのうえで、採用するかどうか決めてください。',
  ]);

export const renderDeclineComment = ({ reason, handoff, aborted = false, runUrl = '' }) => {
  const lines = [
    MARKER,
    '自動修正を試みましたが、TrainLCD/MobileApp のコードでは直せないと判断しました。',
    '',
    reason === '' ? '理由は記録されていません。' : reason,
  ];
  if (handoff !== '') {
    lines.push('', `対応先: [TrainLCD/${handoff}](${HANDOFF_REPOSITORIES[handoff]})`);
  }
  // 判断を書いたあとで実行が落ちた場合。判断は判断として伝えたうえで、実行が
  // 最後まで進んでいないことも書く。判断だけ書くと最後まで動いたように読め、
  // 失敗だけ書くと判断のほうが埋もれる。
  if (aborted) {
    lines.push(
      '',
      `上の理由を書き残したあと、実行そのものは最後まで進んでいません。実行ログ: ${runUrl}`
    );
  }
  lines.push('', 'このコメントを消すと、次に条件を満たしたときにもう一度試します。');
  return withFooter(lines);
};

export const renderFailureComment = ({ stage, runUrl, excerpt = '' }) => {
  const { summary, hint } = FAILURE_STAGES[stage] ?? FAILURE_STAGES['agent-failed'];
  const lines = [
    ERROR_MARKER,
    '自動修正が最後まで進みませんでした。このフィードバックはまだ手つかずです。',
    '',
    `止まった箇所: ${summary}`,
    hint,
  ];
  if (excerpt !== '') {
    lines.push('', '読めなかった内容の先頭:', '', '```text', excerpt, '```');
  }
  lines.push('', `実行ログ: ${runUrl}`);
  return withFooter(lines);
};

// どの場合でも action は linked / declined / failed のどれかになる。「何も
// 返さない」を作らないこと。返さないまま終えると、その issue はそのまま
// 放置される。
export const decideComment = ({ prUrl, verdictResult, claudeOutcome, runUrl }) => {
  const url = typeof prUrl === 'string' ? prUrl.trim() : '';
  const completed = claudeOutcome === 'success';

  if (url !== '') {
    return { action: 'linked', body: renderLinkComment(url) };
  }

  if (verdictResult?.status === 'ok' && verdictResult.verdict.outcome === 'declined') {
    return {
      action: 'declined',
      body: renderDeclineComment({ ...verdictResult.verdict, aborted: !completed, runUrl }),
    };
  }

  // 修正したと報告されたのに PR が無い場合。判断はあるので、どこで止まったのかを
  // 名指しできる。
  if (verdictResult?.status === 'ok') {
    return { action: 'failed', body: renderFailureComment({ stage: 'pr-missing', runUrl }) };
  }

  if (verdictResult?.status === 'invalid') {
    return {
      action: 'failed',
      body: renderFailureComment({
        stage: 'invalid-verdict',
        runUrl,
        excerpt: verdictResult.excerpt ?? '',
      }),
    };
  }

  // 判断が無い場合、どこまで進んだのかは Claude のステップの結果から分かる。
  // skipped なら、手前のステップで落ちてエージェントまで届いていない。
  const stage =
    claudeOutcome === 'skipped' || !claudeOutcome
      ? 'not-reached'
      : completed
        ? 'no-verdict'
        : 'agent-failed';
  return { action: 'failed', body: renderFailureComment({ stage, runUrl }) };
};

const readOptionalFile = async (path) => {
  if (!path) {
    return '';
  }
  try {
    return await readFile(path, 'utf8');
  } catch (error) {
    if (error?.code === 'ENOENT') {
      return '';
    }
    throw error;
  }
};

const main = async () => {
  const verdictResult = parseVerdict(await readOptionalFile(process.env.VERDICT_PATH));
  const { action, body } = decideComment({
    prUrl: process.env.PR_URL ?? '',
    verdictResult,
    claudeOutcome: process.env.CLAUDE_OUTCOME ?? '',
    runUrl: process.env.RUN_URL ?? '',
  });

  if (process.env.GITHUB_OUTPUT) {
    await appendFile(process.env.GITHUB_OUTPUT, `action=${action}\n`, 'utf8');
  }

  const outputPath = process.env.OUTPUT_PATH;
  if (!outputPath) {
    throw new Error('環境変数 OUTPUT_PATH は必須です');
  }
  await writeFile(outputPath, body, 'utf8');
  console.log(`issue へ投稿する内容を書き出しました (${action})`);
};

// テストから関数だけを import できるよう、直接起動されたときだけ main() を走らせる。
const isDirectRun = () => {
  const entry = process.argv[1];
  if (!entry) {
    return false;
  }
  try {
    return import.meta.url === pathToFileURL(realpathSync(entry)).href;
  } catch {
    return false;
  }
};

if (isDirectRun()) {
  main().catch((error) => {
    console.error(`::error::コメント本文の組み立てに失敗しました: ${error.message}`);
    process.exitCode = 1;
  });
}
